import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# Fused GroupNorm + Scale kernel
groupnorm_scale_cpp_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>

__global__ void groupnorm_scale_kernel(
    const float* input,
    float* output,
    const float* weight,  // gamma
    const float* bias,    // beta
    const float* scale,   // additional scale parameter
    int batch_size,
    int channels,
    int height,
    int width,
    int num_groups,
    float eps) {

    int C = channels;
    int G = num_groups;
    int C_per_G = C / G;
    int HxW = height * width;

    // Grid-stride loop for batch
    for (int b = blockIdx.x; b < batch_size; b += gridDim.x) {
        int group = blockIdx.y;
        int C_start = group * C_per_G;
        int C_end = C_start + C_per_G;

        // Shared memory for reduction
        const int warpSize = 64;
        const int max_threads = 256;
        __shared__ float s_sum[max_threads];
        __shared__ float s_sq_sum[max_threads];

        float sum = 0.0f;
        float sq_sum = 0.0f;

        // Each thread processes multiple channels
        for (int c_rel = threadIdx.x; c_rel < C_per_G; c_rel += blockDim.x) {
            int c = C_start + c_rel;
            const float* input_ptr = input + b * C * HxW + c * HxW;

            for (int i = 0; i < HxW; i++) {
                float val = input_ptr[i];
                sum += val;
                sq_sum += val * val;
            }
        }

        // Warp reduction
        for (int offset = warpSize / 2; offset > 0; offset /= 2) {
            sum += __shfl_down(sum, offset);
            sq_sum += __shfl_down(sq_sum, offset);
        }

        // Store warp results in shared memory for final reduction
        int lane_id = threadIdx.x % warpSize;
        int warp_id = threadIdx.x / warpSize;

        if (lane_id == 0) {
            s_sum[warp_id] = sum;
            s_sq_sum[warp_id] = sq_sum;
        }

        __syncthreads();

        // Final reduction
        if (threadIdx.x == 0) {
            float final_sum = 0.0f;
            float final_sq_sum = 0.0f;
            for (int i = 0; i < (blockDim.x + warpSize - 1) / warpSize; i++) {
                final_sum += s_sum[i];
                final_sq_sum += s_sq_sum[i];
            }

            int N = C_per_G * HxW;
            float mean = final_sum / N;
            float var = final_sq_sum / N - mean * mean;
            float std = sqrtf(var + eps);

            s_sum[0] = mean;
            s_sq_sum[0] = std;
        }

        __syncthreads();

        float mean = s_sum[0];
        float std = s_sq_sum[0];
        float inv_std = 1.0f / std;

        // Apply normalization, scaling, and multiply by scale parameter
        for (int c_rel = threadIdx.x; c_rel < C_per_G; c_rel += blockDim.x) {
            int c = C_start + c_rel;
            const float* input_ptr = input + b * C * HxW + c * HxW;
            float* output_ptr = output + b * C * HxW + c * HxW;

            float gamma = weight[c];
            float beta = bias[c];
            float scale_val = scale[c];  // Additional scale parameter

            for (int i = 0; i < HxW; i++) {
                output_ptr[i] = (input_ptr[i] - mean) * inv_std * gamma * scale_val + beta;
            }
        }
    }
}

torch::Tensor groupnorm_scale_hip(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor scale,
    int num_groups,
    float eps) {

    auto batch_size = input.size(0);
    auto channels = input.size(1);
    auto height = input.size(2);
    auto width = input.size(3);

    auto output = torch::empty_like(input);

    const int max_threads = 256;
    dim3 threads(max_threads);
    dim3 blocks(batch_size, num_groups);

    groupnorm_scale_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        scale.data_ptr<float>(),
        batch_size,
        channels,
        height,
        width,
        num_groups,
        eps);

    return output;
}
"""

# Fused MaxPool + Clamp kernel
maxpool_clamp_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void maxpool_clamp_kernel(
    const float* input,
    float* output,
    int batch_size,
    int channels,
    int in_height,
    int in_width,
    int out_height,
    int out_width,
    int kernel_size,
    int stride,
    int padding,
    float clamp_min,
    float clamp_max) {

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int bz = blockIdx.z;

    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int out_x = bx * blockDim.x + tx;
    int out_y = by * blockDim.y + ty;

    if (out_x >= out_width || out_y >= out_height) return;

    // Process all channels for all batches
    for (int b = 0; b < batch_size; b++) {
        for (int c = 0; c < channels; c++) {
            // Calculate input window
            int in_x_start = out_x * stride - padding;
            int in_y_start = out_y * stride - padding;

            float max_val = -1e20f;

            for (int ky = 0; ky < kernel_size; ky++) {
                for (int kx = 0; kx < kernel_size; kx++) {
                    int in_x = in_x_start + kx;
                    int in_y = in_y_start + ky;

                    if (in_x >= 0 && in_x < in_width && in_y >= 0 && in_y < in_height) {
                        int idx = b * channels * in_height * in_width + 
                                  c * in_height * in_width + 
                                  in_y * in_width + in_x;
                        float val = input[idx];
                        if (val > max_val) {
                            max_val = val;
                        }
                    }
                }
            }

            // Apply clamp
            max_val = max(min(max_val, clamp_max), clamp_min);

            int out_idx = b * channels * out_height * out_width +
                          c * out_height * out_width +
                          out_y * out_width + out_x;
            output[out_idx] = max_val;
        }
    }
}

torch::Tensor maxpool_clamp_hip(
    torch::Tensor input,
    int kernel_size,
    float clamp_min,
    float clamp_max) {

    auto batch_size = input.size(0);
    auto channels = input.size(1);
    auto in_height = input.size(2);
    auto in_width = input.size(3);

    int stride = kernel_size;  // Default stride equals kernel size for MaxPool2d
    int padding = 0;

    int out_height = (in_height + 2 * padding - kernel_size) / stride + 1;
    int out_width = (in_width + 2 * padding - kernel_size) / stride + 1;

    auto output = torch::empty({batch_size, channels, out_height, out_width}, input.options());

    const int block_size = 16;
    dim3 threads(block_size, block_size);
    dim3 blocks((out_width + block_size - 1) / block_size, 
                (out_height + block_size - 1) / block_size,
                1);

    maxpool_clamp_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        channels,
        in_height,
        in_width,
        out_height,
        out_width,
        kernel_size,
        stride,
        padding,
        clamp_min,
        clamp_max);

    return output;
}
"""

groupnorm_scale = load_inline(
    name="groupnorm_scale",
    cpp_sources=groupnorm_scale_cpp_source,
    functions=["groupnorm_scale_hip"],
    verbose=True,
)

maxpool_clamp = load_inline(
    name="maxpool_clamp",
    cpp_sources=maxpool_clamp_cpp_source,
    functions=["maxpool_clamp_hip"],
    verbose=True,
)


class ModelNew(nn.Module):
    """
    Optimized model with fused custom HIP kernels for GroupNorm+Scale and MaxPool+Clamp.
    """
    def __init__(self, in_channels, out_channels, kernel_size, num_groups, scale_shape, maxpool_kernel_size, clamp_min, clamp_max):
        super(ModelNew, self).__init__()
        # Keep Conv2d (highly optimized cuDNN)
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)

        # Replace GroupNorm with fused operation (we'll handle it ourselves)
        self.num_groups = num_groups
        self.eps = 1e-5
        self.out_channels = out_channels

        # GroupNorm learnable parameters (gamma and beta)
        self.weight = nn.Parameter(torch.ones(out_channels))
        self.bias = nn.Parameter(torch.zeros(out_channels))

        # Scale parameter
        self.scale = nn.Parameter(torch.ones(scale_shape))

        # Replace MaxPool2d with fused kernel
        self.maxpool_kernel_size = maxpool_kernel_size
        self.clamp_min = clamp_min
        self.clamp_max = clamp_max

        # Load custom kernels
        self.groupnorm_scale_fn = groupnorm_scale
        self.maxpool_clamp_fn = maxpool_clamp

    def forward(self, x):
        """
        Args:
            x: Input tensor of shape (batch_size, in_channels, height, width).
        Returns:
            Output tensor of shape (batch_size, out_channels, height', width').
        """
        # Step 1: Conv2d (keep standard - already optimized in cuDNN)
        x = self.conv(x)

        # Step 2: Fused GroupNorm + Scale
        # Reshape scale from (out_channels, 1, 1) to (out_channels,) for easier indexing
        scale_flat = self.scale.squeeze()
        x = self.groupnorm_scale_fn.groupnorm_scale_hip(
            x, 
            self.weight, 
            self.bias, 
            scale_flat, 
            self.num_groups, 
            self.eps
        )

        # Step 3: Fused MaxPool + Clamp
        x = self.maxpool_clamp_fn.maxpool_clamp_hip(
            x,
            self.maxpool_kernel_size,
            self.clamp_min,
            self.clamp_max
        )

        return x

