        # Scale parameter
        self.scale = nn.Parameter(torch.ones(scale_shape))

        # MaxPool and Clamp parameters
        self.maxpool_kernel_size = maxpool_kernel_size
        self.clamp_min = clamp_min
        self.clamp_max = clamp_max

        # Load custom kernels
        self.groupnorm_scale_fn = groupnorm_scale
        self.maxpool_clamp_fn = maxpool_clamp

    def forward(self, x):
        """
        Args:
            x: Input tensor of shape (batch_size, in_channels, height, width).
        Returns:
            Output tensor of shape (batch_size, out_channels, height', width').
        """
        # Step 1: Conv2d (keep standard - already optimized in cuDNN)
        x = self.conv(x)

        # Step 2: Fused GroupNorm + Scale
        # Reshape scale from (out_channels, 1, 1) to (out_channels,)
        scale_flat = self.scale.squeeze()
        x = self.groupnorm_scale_fn.groupnorm_scale_hip(
