groupnorm_scale_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void groupnorm_scale_kernel(
    const float* input,
    float* output,
    const float* weight,  // gamma
    const float* bias,    // beta
    const float* scale,   // additional scale parameter
    int batch_size,
    int channels,
    int height,
    int width,
    int num_groups,
    float eps) {

    int C = channels;
    int G = num_groups;
    int C_per_G = C / G;
    int HxW = height * width;

    // Each thread block processes one (batch, group) pair
    int batch_idx = blockIdx.x;
    int group_idx = blockIdx.y;

    if (batch_idx >= batch_size || group_idx >= G) return;

    int C_start = group_idx * C_per_G;
    int C_end = C_start + C_per_G;
    int N = C_per_G * HxW;

    // Shared memory for mean and std
    __shared__ float mean_shared;
    __shared__ float inv_std_shared;

    // Compute sum and sum of squares using warp reduction
    float local_sum = 0.0f;
    float local_sq_sum = 0.0f;

    // Each thread processes multiple elements
    for (int i = threadIdx.x; i < N; i += blockDim.x) {
        // Convert linear index to channel and spatial
        int c_rel = i / HxW;
        int hw_idx = i % HxW;
        int c = C_start + c_rel;

        int idx = batch_idx * C * HxW + c * HxW + hw_idx;
        float val = input[idx];

        local_sum += val;
        local_sq_sum += val * val;
    }

    // Warp reduction using shfl_down
    #pragma unroll
    for (int offset = 32; offset > 0; offset /= 2) {
        local_sum += __shfl_down(local_sum, offset);
        local_sq_sum += __shfl_down(local_sq_sum, offset);
    }

    // Final reduction across warps - use first thread of each warp
    __shared__ float warp_sums[8];
    __shared__ float warp_sq_sums[8];

    int lane = threadIdx.x % 32;
    int warp_id = threadIdx.x / 32;

    if (lane == 0 && warp_id < 8) {
        warp_sums[warp_id] = local_sum;
        warp_sq_sums[warp_id] = local_sq_sum;
    }

    __syncthreads();

    if (threadIdx.x == 0) {
        float final_sum = 0.0f;
        float final_sq_sum = 0.0f;

        int num_warps = (blockDim.x + 31) / 32;
        for (int w = 0; w < num_warps && w < 8; w++) {
            final_sum += warp_sums[w];
            final_sq_sum += warp_sq_sums[w];
        }

        float mean = final_sum / N;
        float var = final_sq_sum / N - mean * mean;
        float std = sqrtf(fmaxf(var, 0.0f) + eps);

        mean_shared = mean;
        inv_std_shared = 1.0f / (std + 1e-8f);
    }

    __syncthreads();

    float mean = mean_shared;
    float inv_std = inv_std_shared;

    // Apply normalization, scaling
    for (int i = threadIdx.x; i < N; i += blockDim.x) {
        int c_rel = i / HxW;
        int hw_idx = i % HxW;
        int c = C_start + c_rel;

        int idx = batch_idx * C * HxW + c * HxW + hw_idx;
        float val = input[idx];
        float normalized = (val - mean) * inv_std;

        // Apply gamma, scale, and beta
        output[idx] = normalized * weight[c] * scale[c] + bias[c];
    }
}

torch::Tensor groupnorm_scale_hip(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor scale,
    int num_groups,
    float eps) {

    auto batch_size = input.size(0);
    auto channels = input.size(1);
    auto height = input.size(2);
    auto width = input.size(3);

    auto output = torch::empty_like(input);

    const int threads = 256;
    dim3 blocks(batch_size, num_groups);

    groupnorm_scale_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        scale.data_ptr<float>(),
        batch_size,
        channels,
        height,
        width,
        num_groups,
        eps);

    return output;
}
"""

