#include <hip/hip_runtime.h>

__global__ void maxpool_clamp_kernel(
    const float* input,
    float* output,
    int out_height,
    int out_width,
    int kernel_size,
    int stride,
    float clamp_min,
    float clamp_max) {

    // Each block processes one (batch, channel) pair
    int batch_idx = blockIdx.z;
    int channel_idx = blockIdx.y;
    int out_x = blockIdx.x * blockDim.x + threadIdx.x;
    int out_y = threadIdx.y;

    if (out_x >= out_width || out_y >= out_height) return;

    // Constants for this input
    const int in_height = out_height * stride;
    const int in_width = out_width * stride;
    const int HxW = in_height * in_width;
    const int nC = gridDim.y; // Number of channels

    // Base input offset for this batch and channel
    const float* input_base = input + batch_idx * nC * HxW + channel_idx * HxW;
    float* output_base = output + batch_idx * nC * (out_height * out_width) + channel_idx * (out_height * out_width);

    // Find max in the kernel window
    float max_val = -1e20f;

    int in_x_start = out_x * stride;
    int in_y_start = out_y * stride;

    #pragma unroll
    for (int ky = 0; ky < 4; ky++) {
        #pragma unroll
        for (int kx = 0; kx < 4; kx++) {
            int in_x = in_x_start + kx;
            int in_y = in_y_start + ky;

            if (in_x < in_width && in_y < in_height) {
                float val = input_base[in_y * in_width + in_x];
                if (val > max_val) {
                    max_val = val;
                }
            }
        }
    }

    // Apply clamp
    max_val = fmaxf(fminf(max_val, clamp_max), clamp_min);

    output_base[out_y * out_width + out_x] = max_val;
}

torch::Tensor maxpool_clamp_hip(
    torch::Tensor input,
    int kernel_size,
    float clamp_min,
    float clamp_max) {

    auto batch_size = input.size(0);
    auto channels = input.size(1);
    auto in_height = input.size(2);
    auto in_width = input.size(3);

    int stride = kernel_size;

    int out_height = (in_height - kernel_size) / stride + 1;
    int out_width = (in_width - kernel_size) / stride + 1;

    auto output = torch::empty({batch_size, channels, out_height, out_width}, input.options());

    const int block_x = 16;
    const int block_y = 16;
    dim3 threads(block_x, block_y);

    // Blocks for output spatial dimensions, channels, and batches
    dim3 blocks((out_width + block_x - 1) / block_x, channels, batch_size);

    // Limit channel dimension if too large
    if (blocks.y > 65535) {
        blocks.y = 1;
        blocks.z = batch_size * channels;
    }

    maxpool_clamp_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        out_height,
        out_width,
        kernel_size,
        stride,
        clamp_min,
        clamp_max);

    return output;
}
